{"command": "cd /workspace/reference_work && python3 - <<'EOF'
# Faulty variant: uses isinstance(amount,int) which treats bool as int
class FaultyOrder:
    def __init__(self, total_cents):
        self.total_cents = total_cents; self.refunded_cents = 0; self.state = "pending"
    def capture(self): self.state = "paid"
    def refund(self, amount):
        if self.state not in ("paid","partially_refunded"): raise ValueError()
        if not isinstance(amount,int) or amount <= 0: raise ValueError("refund must be a positive integer")
        self.refunded_cents += amount
        self.state = "refunded" if self.refunded_cents == self.total_cents else "partially_refunded"
    def summary(self): return {"state":self.state,"total_cents":self.total_cents,"refunded_cents":self.refunded_cents,"remaining_cents":self.total_cents-self.refunded_cents}

o=FaultyOrder(100); o.capture()
try:
    o.refund(True); print("faulty accepted bool ->", o.summary(), "(regression exposed: expected error but none)")
except ValueError:
    print("faulty raised -> would NOT expose regression")
EOF"}

